{
  "command": "replace_content_by_matching",
  "args": {
    "old_content": "module TopModule(
    input  logic       clk,
    input  logic       reset,
    output logic [9:0] q
);

    // 10-bit synchronous modulo-1000 counter: 0..999, then wrap to 0.
    localparam logic [9:0] MAX_VAL = 10'd999;

    always @(posedge clk) begin
        if (reset) begin
            q <= 10'd0;
        end else begin
            if (q == MAX_VAL)
                q <= 10'd0;
            else
                q <= q + 10'd1;
        end
    end

endmodule
",
    "new_content": "module TopModule(
    input  logic       clk,
    input  logic       reset,
    output logic [9:0] q
);

    // 10-bit synchronous modulo-1000 counter: 0..999, then wrap to 0.
    localparam logic [9:0] MAX_VAL = 10'd999;

    always @(posedge clk) begin
        if (reset) begin
            q <= 10'd0;
        end else begin
            if (q == MAX_VAL)
                q <= 10'd0;
            else
                q <= q + 10'd1;
        end
    end

endmodule
"
  }
}

